					{ startIndex: o.startIndex + delta, endIndex: o.endIndex },
					"left",
				);
			} else if (type === "right") {
				commit(
					{ startIndex: o.startIndex, endIndex: o.endIndex + delta },
					"right",
				);
			} else {
				const span = o.endIndex - o.startIndex;
				let s = o.startIndex + delta;
				let e2 = s + span;
				if (s < 0) {
					s = 0;
					e2 = span;
				}
